function DateTimeControl_Change(e,t,n){var a=document.getElementById(t),l=document.getElementById(n);if(e.checked){if(""==a.value){var r=new Date,s=new Number(r.getMonth()+1);a.value=r.getDate()+"."+s+"."+r.getFullYear();var u=r.getMinutes();u<10&&(u="0"+u),l.value=r.getHours()+":"+u}a.readOnly=!1,a.className="TextBoxFace",l.readOnly=!1,l.className="TextBoxFace"}else a.value="",a.readOnly=!0,a.className="ReadOnlyInputClass",l.value="",l.readOnly=!0,l.className="ReadOnlyInputClass"}function DateTimeControl_SetReadOnly(e,t){var n=document.getElementById(e),a=document.getElementById(t);n.readOnly=!0,n.className="ReadOnlyInputClass",a.readOnly=!0,a.className="ReadOnlyInputClass"}function DateTimeControl_CheckTime(e){var t=e.value;if(""==t)return!1;if(-1==t.indexOf(":")){var n,a="00";if(4==t.length)n=t.substr(0,2),a=t.substr(2,2);else if(3==t.length)n=t.substr(0,1),a=t.substr(1,2);else if(2==t.length)n=t.substr(0,2);else{if(1!=t.length)return!1;n=t.substr(0,1)}}else{if(!(t.length<6))return!1;n=t.substring(0,t.indexOf(":")),a=t.substring(t.indexOf(":")+1)}var l=parseInt(n),r=parseInt(a);if(isNaN(l)||isNaN(r))return!1;if(l>=0&&l<24&&r>=0&&r<60){var s=r<10?"0"+r:r;return e.value=l+":"+s,!0}return!1}function DateTimeControl_OnBlur(e,t,n){var a=document.getElementById(t);if(""==document.getElementById(e).value&&""==a.value)return!0;var l=DateTimeControl_CheckTime(a);return l||(window.alert(n),a.focus()),l}